function validateRow(r){if(!r||typeof r.id!=='string'||!/^[-a-zA-Z0-9_]{1,80}$/.test(r.id)||typeof r.source!=='string'||r.source.length<1||r.source.length>100||!/^\d{4}-\d{2}-\d{2}$/.test(r.date)||Number.isNaN(Date.parse(r.date+'T00:00:00Z'))||new Date(r.date+'T00:00:00Z').toISOString().slice(0,10)!==r.date||!Number.isSafeInteger(r.cents)||Math.abs(r.cents)>100000000||r.currency!=='USD'||!['pending','received','refund'].includes(r.status)||r.status==='refund'&&r.cents>0||r.status!=='refund'&&r.cents<0)fail('Invalid transaction: use a real date, USD cents and a matching status.');}
function totals(s){return {received:s.ledger.filter(r=>r.status!=='pending').reduce((n,r)=>n+r.cents,0),pending:s.ledger.filter(r=>r.status==='pending').reduce((n,r)=>n+r.cents,0),spend:0,verified:false};}
function csv(s){const esc=v=>'"'+String(v).replace(/"/g,'""').replace(/^[=+@\-\t\r]/,"'$&")+'"';return ['id,date,source,usd_cents,status,verification',...s.ledger.map(r=>[r.id,r.date,r.source,r.cents,r.status,'owner-entered; unverified'].map(esc).join(','))].join('\r\n');}
